from qb import q, write

NBY = ["python-developer", "backend-developer", "junior-ai-engineer", "data-scientist"]
ITEMS = [
    q("aws", "easy", ["iam"], "What is IAM in AWS and why is least privilege important?", "IAM controls who or what can do which actions on which AWS resources through users, roles and policies. Least privilege means granting only the permissions needed, so a leaked credential or a bug can do limited damage.", ["Users, roles, policies", "Grant only what is needed", "Limits damage of leaks"], ["Why prefer roles over long-lived access keys?"]),
    q("aws", "medium", ["storage"], "When would you choose S3, EBS or a database such as RDS for storing data?", "S3 stores objects such as files, images and backups cheaply and durably, EBS is a disk attached to one EC2 instance, and RDS is a managed relational database for structured data with queries and transactions. Choose by access pattern.", ["Objects vs disks vs relational data", "Match storage to access pattern", "Durability and cost"], ["How do you control access to a private S3 bucket?"]),
    q("aws", "medium", ["lambda", "events"], "How would you build a pipeline where uploading a file to S3 triggers processing automatically?", "Configure an S3 event notification to invoke a Lambda function or send a message to a queue, process the file there, write results to storage or a database and handle failures with retries and a dead-letter queue. Make processing idempotent because events can repeat.", ["S3 event triggers Lambda or queue", "Retries and dead-letter queue", "Idempotent processing"], ["What if the file is larger than Lambda can handle?"]),
    q("aws", "hard", ["reliability"], "How would you design a web application on AWS so that it keeps working if one availability zone fails?", "Run instances in at least two availability zones behind a load balancer with auto scaling, use a multi-AZ managed database with automatic failover, keep state out of the instances and use health checks. Test failover and monitor.", ["Multi-AZ everywhere", "Load balancer and auto scaling", "Test failover"], ["What would a multi-region design add and cost?"]),
    q("aws", "medium", ["monitoring"], "What would you monitor for a production service and how would you be alerted?", "Track request rate, errors, latency and resource use plus business metrics, collect logs centrally and set alarms with sensible thresholds that notify the team. Alerts should be actionable to avoid fatigue.", ["Errors, latency, saturation", "Central logs", "Actionable alerts"], ["How do you pick a threshold?"]),
    q("cloud", "medium", ["infrastructure-as-code"], "What is infrastructure as code and why is it better than creating resources by hand?", "It describes infrastructure in files, with tools such as Terraform or CloudFormation, so environments can be created repeatably, reviewed and versioned. Manual changes drift and cannot be reproduced reliably.", ["Infrastructure in version-controlled files", "Repeatable environments", "Avoids drift"], ["How do you manage the state file safely?"]),
    q("data", "easy", ["etl"], "Explain the difference between ETL and ELT and when each is used.", "ETL transforms data before loading it into the warehouse, while ELT loads raw data first and transforms it inside the warehouse. ELT suits modern warehouses with strong compute and keeps raw data for reprocessing.", ["Order of transform and load", "ELT keeps raw data", "Choose by tooling and volume"], ["What is a data lake?"]),
    q("data", "medium", ["data-quality"], "How would you make sure a daily data pipeline produces trustworthy data?", "Validate inputs and outputs with checks such as row counts, nulls, ranges and duplicates, make loads idempotent, log run metadata, alert on failures and keep the raw data so runs can be repeated.", ["Automated quality checks", "Idempotent loads", "Alerts and raw data kept"], ["What would you do when the source data is wrong?"]),
    q("data", "hard", ["warehouse"], "What is a star schema and why is it used in analytics?", "A star schema has a central fact table of measurable events, such as sales, linked to dimension tables such as customer, product and date. It makes analytical queries simple and fast to aggregate, at the cost of some duplication.", ["Fact and dimension tables", "Simple aggregation queries", "Denormalised on purpose"], ["How do you handle a dimension that changes over time?"]),
    q("sql", "medium", ["window-functions"], "How would you find the month-over-month growth of sales per product in SQL?", "Aggregate sales per product and month, then use LAG over a partition by product ordered by month to get the previous month and compute the difference divided by the previous value, handling nulls and zero.", ["Aggregate by month", "LAG window function", "Handle zero and null"], ["How do you handle months with no sales?"]),
    q("sql", "hard", ["optimisation"], "A report query takes ten minutes on a table with 200 million rows. How do you speed it up?", "Check the query plan, filter early, select only needed columns, use partitioning or indexes that match the filters, pre-aggregate into summary tables and consider columnar storage. Verify results are still correct.", ["Read the plan", "Partition and index for the filters", "Pre-aggregate"], ["When is a materialised view a good idea?"]),
    q("python", "easy", ["python"], "What are list comprehensions and generator expressions, and how do they differ?", "A list comprehension builds the whole list in memory immediately, while a generator expression produces items lazily one at a time. Use a generator for large or streaming data.", ["Eager vs lazy", "Memory difference", "Square brackets vs parentheses"], ["Can you iterate over a generator twice?"]),
    q("python", "medium", ["pandas", "performance"], "Why is a Python for loop over DataFrame rows slow and what do you use instead?", "Row loops run Python code per row, which is slow. Use vectorised column operations, built-in aggregations, apply only as a last resort and chunked processing or a faster engine for large data.", ["Per-row Python is slow", "Vectorised operations", "Chunking or faster engines"], ["How would you profile a slow pandas script?"]),
    q("python", "medium", ["boto3", "automation"], "How would you write a Python script that lists files in an S3 bucket and downloads the ones modified today?", "Use boto3 with credentials from a role or environment, list objects with pagination, filter by last modified date and download each with error handling and logging. Never hard-code keys.", ["boto3 with a role", "Pagination", "Filter, download, handle errors"], ["Why is pagination needed?"]),
    q("ml", "medium", ["ml-pipeline"], "How would you take a model from a notebook to a service that other applications can use?", "Move preprocessing and prediction into tested code, package the model with its version, serve it behind an API with validation, containerise it, deploy with monitoring and plan retraining.", ["Clean, tested code", "Versioned model behind an API", "Monitoring and retraining"], ["What is the difference between batch and real-time prediction?"]),
    q("ml", "medium", ["metrics"], "Which metrics would you use for a regression model predicting delivery time and how do you explain them to a business user?", "Use MAE, which is the average error in minutes and easy to explain, and RMSE, which punishes large errors more, and compare against a simple baseline. Show errors by segment.", ["MAE and RMSE", "Compare with a baseline", "Explain in business units"], ["When is MAPE a bad choice?"]),
    q("ai", "medium", ["rag"], "How would you build a question-answering assistant over a company's documents stored in S3?", "Extract and chunk the documents, create embeddings, store them in a vector database, retrieve the most relevant chunks for each question and have an LLM answer with citations, with access control matching document permissions.", ["Extract, chunk, embed", "Retrieve then answer with citations", "Respect permissions"], ["How would you keep the index up to date?"]),
    q("ai", "hard", ["llm-ops"], "What would you track and control when running an LLM feature in production?", "Track cost, latency, error rates, quality scores and user feedback, version prompts and models, log inputs safely, set rate limits and budgets and add fallbacks if the provider fails.", ["Cost, latency, quality", "Versioning", "Limits and fallbacks"], ["How would you test a prompt change?"]),
    q("devops", "medium", ["ci-cd"], "How would you set up automated deployment for a Python service on AWS?", "On each merge run tests, build a container image, push it to a registry and deploy to a staging environment, run checks and then promote to production with a rollback option. Keep secrets in a manager.", ["Test, build, push, deploy", "Staging then production", "Rollback and secrets"], ["How do you do a zero-downtime deployment?"]),
    q("security", "medium", ["cloud-security"], "What are common cloud security mistakes and how do you avoid them?", "Public buckets, over-broad permissions, secrets in code, unpatched systems and no logging are common. Avoid them with least privilege, private defaults, a secrets manager, patching and audit logs.", ["Public storage and wide permissions", "Secrets in code", "Logging and patching"], ["How would you find a public bucket?"]),
    q("nb-scenario", "medium", ["debugging"], "Scenario: a nightly data job that normally takes 20 minutes now takes 4 hours. How do you investigate?", "Compare with earlier runs, check input volume and shape, look at logs for the slow step, check database locks, missing indexes or resource limits, fix the cause and add timing metrics and alerts.", ["Compare with normal runs", "Find the slow step", "Add timing and alerts"], ["How would you avoid reprocessing everything next time?"], kind="scenario"),
    q("nb-scenario", "hard", ["design"], "Scenario: design a system that ingests millions of sensor readings per hour and lets analysts query them by device and time.", "Ingest through a streaming service or queue, write to partitioned storage by time and device, aggregate into summaries for fast queries and keep raw data cheaply. Handle late and duplicate data.", ["Streaming ingestion", "Time-partitioned storage", "Summaries and late data"], ["How do you handle a device that sends wrong values?"], kind="scenario"),
    q("nb-scenario", "easy", ["teamwork"], "Scenario: a stakeholder wants a report by tomorrow but the data has known quality issues. What do you do?", "Tell them about the issues, show what can be reported reliably, mark uncertain numbers clearly and agree on a plan to fix the data. Do not present doubtful figures as certain.", ["Be transparent", "Report what is reliable", "Plan the fix"], ["How do you document known data issues?"], kind="scenario"),
    q("git", "easy", ["git"], "What is the difference between git fetch and git pull, and how do you undo a commit that is already pushed?", "Fetch downloads remote changes without merging, while pull fetches and merges them. To undo a pushed commit safely use git revert, which creates a new commit that reverses it, instead of rewriting shared history.", ["fetch vs pull", "revert for shared history", "Avoid force-pushing shared branches"], ["When is git reset acceptable?"]),
    q("project", "easy", ["projects"], "Describe a cloud, data or Python automation project of yours. What problem did it solve and what would you improve?", "A strong answer names the problem, tools and your own part, describes a measurable result or lesson and an honest improvement such as monitoring or tests.", ["Problem and own part", "Result or lesson", "Honest improvement"], ["How did you test it?"], kind="scenario", roles=NBY),
]


def build():
    return write("northbay", NBY, ITEMS)


if __name__ == "__main__":
    build()
